import json
import re

output = []
for item in _input.all():
    raw = item.json.get("output")  # get the field containing the string

    if not raw:
        parsed = {"output": {"type": "text", "data": ""}}
    else:
        # Remove markdown ```json blocks
        raw_clean = re.sub(r'^```json\s*|```$', '', raw.strip(), flags=re.MULTILINE)

        try:
            parsed = json.loads(raw_clean)
        except json.JSONDecodeError:
            # fallback if parsing fails
            parsed = {"output": {"type": "text", "data": raw_clean}}

    # Ensure we always have output.type and output.data
    out = parsed.get("output", {})
    if not isinstance(out, dict):
        out = {"type": "text", "data": str(out)}

    final_type = out.get("type", "text")
    final_data = out.get("data", "")

    output.append({
        "output": {
            "type": final_type,
            "data": final_data
        }
    })


return output

