def create_clinical_message(d):
    msg = f"""**CLINICAL SUMMARY**

**# Chief Complaint:** {d['chief_complaint']}\n
**# Duration:** {d['duration']}\n
**# Severity:** {d['severity']}\n

**- Clinical Impression:**
{d['clinical_impression']}

**- Possible Causes:**
"""
    for i, diff in enumerate(d["differentials"], 1):
        msg += f"  {i}. {diff}\n"

    msg += f"""
**- Recommended Action:**
{d['recommended_action']}

**- Care Instructions:**
"""
    for i, step in enumerate(d["care_instructions"], 1):
        msg += f"  {i}. {step}\n"

    return msg.strip()

